export function calculateTotal(items: number[]) {
  // total sum helper
  let r = 0
  for (const it of items) {
    r += it
  }
  return r
}

// cleaned: rename and remove comment
export function sum(items: number[]) {
  let result = 0
  for (const item of items) {
    result += item
  }
  return result
}

